// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    // C's owner is the zero address (unset private _contractOwner).
    address constant OWNER = address(0);

    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address logger, bool status) public {
        // admissible domain: logger must be a fresh key; owner must be able to call
        vm.assume(logger != OWNER);

        vm.prank(OWNER);
        c.setApprovedLogger(logger, status);

        // General rule: after an owner-approved setApprovedLogger(l, s), the
        // stored approval flag for l equals exactly the requested status s.
        assertTrue(c.approvedToLog(logger) == status);
    }
}
